const fs = require('fs');

// Read the audit results
const auditData = JSON.parse(fs.readFileSync('/tmp/audit_results.json', 'utf8'));

// Read package-lock.json to get installed versions
const packageLock = JSON.parse(fs.readFileSync('/root/package-lock.json', 'utf8'));

// Function to get installed version from package-lock.json
function getInstalledVersion(packageName) {
    // Check in packages section (lockfileVersion 3)
    if (packageLock.packages) {
        for (const [path, pkg] of Object.entries(packageLock.packages)) {
            if (path === `node_modules/${packageName}` || path.endsWith(`/node_modules/${packageName}`)) {
                return pkg.version;
            }
        }
    }
    return 'N/A';
}

// Function to get fixed version from range
function getFixedVersion(vuln) {
    if (vuln.fixAvailable === true || (typeof vuln.fixAvailable === 'object' && vuln.fixAvailable.version)) {
        if (typeof vuln.fixAvailable === 'object') {
            return vuln.fixAvailable.version;
        }
        // Try to extract from range
        const range = vuln.range;
        if (!range) return 'N/A';

        // Look at the vulnerability details to get the fixed version
        if (Array.isArray(vuln.via)) {
            for (const item of vuln.via) {
                if (typeof item === 'object' && item.range) {
                    // Parse range like "<7.23.2" to get fixed version
                    const match = item.range.match(/<(\d+\.\d+\.\d+)/);
                    if (match) return match[1];

                    // Parse range like ">=7.0.0 <7.5.2"
                    const match2 = item.range.match(/<(\d+\.\d+\.\d+)$/);
                    if (match2) return match2[1];
                }
            }
        }
        return 'See advisory';
    }
    return 'N/A';
}

// Collect HIGH and CRITICAL vulnerabilities
const results = [];

for (const [packageName, vuln] of Object.entries(auditData.vulnerabilities)) {
    if (vuln.severity === 'high' || vuln.severity === 'critical') {
        // Get installed version
        const installedVersion = getInstalledVersion(packageName);

        // Process each vulnerability detail
        if (Array.isArray(vuln.via)) {
            for (const item of vuln.via) {
                if (typeof item === 'object' && item.url) {
                    // This is a direct vulnerability
                    const cveMatch = item.url.match(/GHSA-[a-z0-9-]+/);
                    const cveId = cveMatch ? cveMatch[0] : 'N/A';

                    // Get CVSS score
                    const cvssScore = item.cvss && item.cvss.score ? item.cvss.score : 'N/A';

                    // Get fixed version from range
                    let fixedVersion = 'N/A';
                    if (item.range) {
                        const match = item.range.match(/<(\d+\.\d+\.\d+)/);
                        if (match) fixedVersion = match[1];
                        else {
                            const match2 = item.range.match(/>=[\d.]+ <(\d+\.\d+\.\d+)/);
                            if (match2) fixedVersion = match2[1];
                        }
                    }

                    results.push({
                        package: packageName,
                        version: installedVersion,
                        cveId: cveId,
                        severity: vuln.severity.toUpperCase(),
                        cvssScore: cvssScore,
                        fixedVersion: fixedVersion,
                        title: item.title || 'N/A',
                        url: item.url || 'N/A'
                    });
                }
            }
        }

        // If no direct vulnerabilities found but it's still high/critical (transitive)
        if (results.filter(r => r.package === packageName).length === 0) {
            results.push({
                package: packageName,
                version: installedVersion,
                cveId: 'N/A',
                severity: vuln.severity.toUpperCase(),
                cvssScore: 'N/A',
                fixedVersion: getFixedVersion(vuln),
                title: 'Transitive vulnerability',
                url: 'N/A'
            });
        }
    }
}

// Sort by severity (CRITICAL first) and package name
results.sort((a, b) => {
    if (a.severity !== b.severity) {
        return a.severity === 'CRITICAL' ? -1 : 1;
    }
    return a.package.localeCompare(b.package);
});

// Write CSV
const csv = ['Package,Version,CVE_ID,Severity,CVSS_Score,Fixed_Version,Title,Url'];
for (const result of results) {
    const title = result.title.replace(/"/g, '""'); // Escape quotes
    csv.push(`${result.package},${result.version},${result.cveId},${result.severity},${result.cvssScore},${result.fixedVersion},"${title}",${result.url}`);
}

fs.writeFileSync('/root/security_audit.csv', csv.join('\n'));
console.log(`Wrote ${results.length} vulnerabilities to /root/security_audit.csv`);

